(function(global){'use strict';
  let connection;
  function open(){if(connection)return connection;connection=new Promise((resolve,reject)=>{if(!global.indexedDB)return reject(new Error('Screenshot storage is unavailable in this browser.'));const request=indexedDB.open('gym-stone-records',1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('screenshots',{keyPath:'id'}).createIndex('hash','hash',{unique:true});db.createObjectStore('state',{keyPath:'id'})};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>{db.close();connection=undefined};resolve(db)};request.onerror=()=>reject(new Error('Screenshot storage could not be opened. Check browser storage settings.'));request.onblocked=()=>reject(new Error('Close other Gym Stone tabs and try again.'))});connection.catch(()=>connection=undefined);return connection}
  async function read(store,key){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),r=tx.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Saved records could not be read.'))})}
  async function getRecords(){const state=await read('state','workouts');return state?.records||null}
  async function putRecords(records){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put({id:'workouts',records});tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(tx.error||new Error('Workout records could not be saved.'))})}
  async function list(){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('screenshots','readonly'),r=tx.objectStore('screenshots').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Screenshots could not be loaded.'))})}
  async function saveWithRecords(screenshot,records){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(['screenshots','state'],'readwrite');tx.objectStore('screenshots').put(screenshot);tx.objectStore('state').put({id:'workouts',records});tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(tx.error||new Error('The screenshot could not be saved. Your browser may be out of storage.'))})}
  async function deleteWithRecords(id,records){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(['screenshots','state'],'readwrite');tx.objectStore('screenshots').delete(id);tx.objectStore('state').put({id:'workouts',records});tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(tx.error||new Error('The screenshot could not be deleted.'))})}
  global.GymScreenshotStore={open,getRecords,putRecords,list,get:id=>read('screenshots',id),saveWithRecords,deleteWithRecords};
})(window);

